import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Teorema di Gödel","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/bf/bfcd.md","filePath":"lezioni/b_aritmetica-e-numeri/bf/bfcd.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/bf/bfcd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="teorema-di-godel" tabindex="-1">Teorema di Gödel <a class="header-anchor" href="#teorema-di-godel" aria-label="Permalink to “Teorema di Gödel”">​</a></h1><p>Diremo che un sistema è <strong>completo</strong> se conosciamo ogni sua formula.</p><p>Diremo che un sistema è <strong>coerente</strong> se posso dimostrare tutte le sue formule, cioè per ogni sua formula posso dire se è vera oppure falsa.</p><p>Il teorema di Gödel dice che:</p><h2 id="dato-un-qualunque-sistema-formale-esso-o-e-coerente-oppure-e-completo" tabindex="-1">Dato un qualunque sistema formale esso o è coerente oppure è completo <a class="header-anchor" href="#dato-un-qualunque-sistema-formale-esso-o-e-coerente-oppure-e-completo" aria-label="Permalink to “Dato un qualunque sistema formale esso o è coerente oppure è completo”">​</a></h2><p>Cioè un sistema formale non può essere coerente e completo allo stesso tempo: se conosco tutte le formule del sistema allora ci sarà una formula per cui non posso dire se è vera oppure falsa; viceversa, se per ogni formula che conosco so se è vera oppure è falsa, significa che ci sono altre formule nel sistema che ancora non ho individuato.</p><p>Vediamone un accenno di dimostrazione.</p><p>Ogni sistema formale si può trasformare in un sottoinsieme di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> come abbiamo visto nelle pagine precedenti e ad ogni formula corrisponde il suo numero di Gödel.</p><p>Gödel mostrò che tra le varie formule è possibile individuare una formula chiamata <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> che, una volta ritrasformata dal suo numero, dica:</p><p><strong>[&quot;La formula <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> non è dimostrabile&quot;]{.text-red}</strong></p><blockquote><p><strong>Nota:</strong> Ricordo che dimostrabile significa che posso dire se è vera oppure falsa.</p></blockquote><p>Anche qui ci troviamo di fronte ad un paradosso, infatti:</p><ul><li>Se <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> è dimostrabile, allora siccome vale &quot;La formula <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> non è dimostrabile&quot;, ne segue che <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> non è dimostrabile.</li><li>Se <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> non è dimostrabile, allora la formula &quot;La formula <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> non è dimostrabile&quot; è vera e quindi dimostrabile.</li></ul><p>Per rincarare la dose, Gödel applicò il suo ragionamento all&#39;intera aritmetica e dimostrò che l&#39;aritmetica nel suo complesso o è completa oppure è coerente.</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};